474	// ---- 存储操作 ----
475	
476	// CreateVoteProposal 创建一项投票提案。
477	// 同编号且全部内容相同的重试返回已存在提案（existed=true）且不改变任何状态；
478	// 同编号内容不同（或编号已被 register 来源占用）返回 ErrProposalConflict。
479	// 非法条件整项拒绝，不落盘任何部分变化。
480	func (s *Store) CreateVoteProposal(in *CreateVoteInput) (view *VoteProposalView, existed bool, err error) {
481		spec, err := validateProposalInput(in)
482		if err != nil {
483			return nil, false, err
484		}
485		commit, err := s.begin()
486		if err != nil {
487			return nil, false, err
488		}
489		defer commit()
490	
491		state, err := s.loadLocked()
492		if err != nil {
493			return nil, false, err
494		}
495		if existing, ok := state.VoteProposals[in.ID]; ok {
496			if !proposalsEqual(existing, in, spec) {
497				return nil, false, fmt.Errorf("%w: voting proposal %s", ErrProposalConflict, in.ID)
498			}
499			v := voteProposalView(existing)
500			return v, true, nil
501		}
502		if _, ok := state.Proposals[in.ID]; ok {
503			// register 不能覆盖投票提案；反向同样拒绝，两种来源共用编号。
504			return nil, false, fmt.Errorf("%w: proposal id %s already registered", ErrProposalConflict, in.ID)
505		}
506	
507		stored := &storedVoteProposal{
508			ID:          in.ID,
509			State:       "voting",
510			Members:     make([]storedMember, 0, len(in.Members)),
511			Delegations: make([]storedDelegation, 0, len(in.Delegations)),
512			Quorum:      in.Quorum,
513			StartAt:     in.StartAt,
514			Deadline:    in.Deadline,
515			TimelockEnd: in.TimelockEnd,
516			Actions:     copyActions(in.Actions),
517			Ballots:     []storedBallot{},
518		}
519		for _, m := range in.Members {
520			stored.Members = append(stored.Members, storedMember{ID: m.ID, Weight: m.Weight})
521		}
522		for _, d := range in.Delegations {
523			stored.Delegations = append(stored.Delegations, storedDelegation{From: d.From, To: d.To})
524		}
525		state.VoteProposals[in.ID] = stored
526		if err := s.commitLocked(state); err != nil {
527			return nil, false, err
528		}
529		return voteProposalView(stored), false, nil
530	}
