211		if existed {
212			fmt.Printf("proposal %s already registered with identical content\n", *id)
213		} else {
214			fmt.Printf("registered passed proposal %s (%d action(s), timelock_end=%d)\n", *id, len(actions), timelock)
215		}
216	}
217	
218	// memberList 收集重复的 --member ID:WEIGHT 参数，保持提交顺序。
219	type memberList []govflow.VoteMember
220	
221	func (m *memberList) String() string { return fmt.Sprint([]govflow.VoteMember(*m)) }
222	func (m *memberList) Set(v string) error {
223		id, weight, err := splitMember(v)
224		if err != nil {
225			return err
226		}
227		*m = append(*m, govflow.VoteMember{ID: id, Weight: weight})
228		return nil
229	}
230	
231	func splitMember(raw string) (string, int64, error) {
232		idx := strings.LastIndex(raw, ":")
233		if idx <= 0 || idx == len(raw)-1 {
234			return "", 0, fmt.Errorf("malformed member %q, expected ID:WEIGHT", raw)
235		}
236		id := raw[:idx]
237		weight, err := strconv.ParseInt(raw[idx+1:], 10, 64)
238		if err != nil {
239			return "", 0, fmt.Errorf("malformed member %q: weight must be int64: %v", raw, err)
240		}
241		return id, weight, nil
242	}
243	
244	// delegationList 收集重复的 --delegate FROM:TO 参数原文，保持提交顺序。
245	// 成员编号本身可含冒号（如 team:alice），FROM 与 TO 两端都可能含冒号，
246	// 因此不能在解析单个参数时切分：必须等完整成员名单齐备后，
247	// 由 resolveDelegations 结合名单确定唯一的切分点。
248	type delegationList []string
249	
250	func (d *delegationList) String() string { return fmt.Sprint([]string(*d)) }
251	func (d *delegationList) Set(v string) error {
252		*d = append(*d, v)
253		return nil
254	}
255	
256	// delegationUsageError 是 --delegate 的参数错误（格式错误或切分有歧义），
257	// 以退出码 2 结束；格式正确但无法匹配名单的错误不属于此类，按域错误退出码 1 处理。
258	type delegationUsageError struct{ reason string }
259	
260	func (e *delegationUsageError) Error() string { return e.reason }
261	
262	// resolveDelegations 结合本次提交的完整成员名单理解每条 FROM:TO 委托原文。
263	// 成员编号保持原文并区分大小写；编号可含冒号，且冒号可以出现在编号开头、
264	// 末尾或连续出现（如 ":alice"、"a:"、"a::b"），所以一条委托原文在每个冒号
265	// 位置都有一种候选切分，切分点两侧的编号仍须各自非空。
266	//
267	// 判定只依据“两端非空”这一纯语法条件与成员名单，不拿自委托/重复/循环等
268	// 业务规则替用户筛选候选：
269	//   - 原文不含冒号，或每个冒号位置的切分都会让某一端为空（如 ":alice"、
270	//     "alice:"、":"、"::"：冒号只出现在首尾、中间再无切分点）：格式错误，
271	//     参数错误（退出码 2）；
272	//   - 存在两端非空的切分，但没有任何一对都在名单里：域错误（退出码 1）；
273	//   - 两对或更多成员同时命中（即使其中某种解释随后会触发自委托、重复或循环）：
274	//     委托有歧义，参数错误（退出码 2），错误列出有歧义的原文与全部成员对；
275	//   - 恰好一对命中：按该对成员创建委托。
276	//
277	// 成员与委托参数在命令行上的排列先后不影响结果：解析前名单已收集完毕。
278	func resolveDelegations(members []govflow.VoteMember, raws []string) ([]govflow.Delegation, error) {
279		roster := make(map[string]bool, len(members))
280		for _, m := range members {
281			roster[m.ID] = true
282		}
283		out := make([]govflow.Delegation, 0, len(raws))
284		for _, raw := range raws {
285			var matches []govflow.Delegation
286			hasNonEmptySplit := false
287			for i := 0; i < len(raw); i++ {
288				if raw[i] != ':' {
289					continue
290				}
291				from, to := raw[:i], raw[i+1:]
292				// 纯语法候选：切分点两侧都非空才算“存在 FROM:TO 写法”。
293				// 编号本身允许以冒号开头、结尾或包含连续冒号，因此位于位置 0
294				// 的冒号产生的空 from、以及结尾冒号产生的空 to 都只是不合法的
295				// 切分点之一，绝不据此提前拒绝整条原文——其他冒号位置仍可能合法。
296				if from == "" || to == "" {
297					continue
298				}
299				hasNonEmptySplit = true
300				if roster[from] && roster[to] {
301					matches = append(matches, govflow.Delegation{From: from, To: to})
302				}
303			}
304			if !hasNonEmptySplit {
305				return nil, &delegationUsageError{fmt.Sprintf("malformed delegation %q, expected FROM:TO with non-empty member ids on both sides", raw)}
306			}
307			switch len(matches) {
308			case 0:
309				return nil, fmt.Errorf("delegation %q does not match any pair of members on the roster", raw)
310			case 1:
311				out = append(out, matches[0])
312			default:
313				pairs := make([]string, len(matches))
314				for i, m := range matches {
315					pairs[i] = fmt.Sprintf("%q delegating to %q", m.From, m.To)
316				}
317				return nil, &delegationUsageError{fmt.Sprintf("ambiguous delegation %q: could mean %s",
318					raw, strings.Join(pairs, " or "))}
319			}
320		}
321		return out, nil
322	}
323	
324	func runCreateVote(args []string) {
325		cf := newCmdFlags("create-vote")
326		id := cf.fs.String("id", "", "proposal id (non-empty)")
327		var members memberList
328		cf.fs.Var(&members, "member", "member ID:WEIGHT with positive int64 weight (repeatable, order irrelevant to equality)")
329		var delegationRaws delegationList
330		cf.fs.Var(&delegationRaws, "delegate", "delegation FROM:TO (repeatable, order irrelevant to equality; either side may itself contain colons and is matched against the full member roster)")
331		quorumRaw := cf.fs.String("quorum", "", "required turnout weight between 1 and total member weight")
332		startRaw := cf.fs.String("start", "", "voting start timestamp (int64, >= 0)")
333		deadlineRaw := cf.fs.String("deadline", "", "voting deadline timestamp (int64, > start)")
334		timelockRaw := cf.fs.String("timelock", "", "timelock end timestamp (int64, >= deadline)")
335		var actions actionList
336		cf.fs.Var(&actions, "action", "action text transfer:<account>:<amount> (repeatable, order preserved)")
337		cf.parse(args)
338		if *id == "" {
339			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
340			os.Exit(2)
341		}
342		quorum := parseIntFlag(cf.fs, "quorum", *quorumRaw)
343		start := parseIntFlag(cf.fs, "start", *startRaw)
344		deadline := parseIntFlag(cf.fs, "deadline", *deadlineRaw)
345		timelock := parseIntFlag(cf.fs, "timelock", *timelockRaw)
346		if len(members) == 0 {
347			fmt.Fprintf(os.Stderr, "usage error: at least one --member ID:WEIGHT is required\n")
348			os.Exit(2)
349		}
350		// 委托切分依赖完整成员名单，必须在打开状态文件之前完成：
351		// 格式错误与歧义是参数错误（退出码 2），无法匹配名单是域错误（退出码 1），
352		// 两种失败都不触碰已有状态文件。
353		delegations, derr := resolveDelegations([]govflow.VoteMember(members), []string(delegationRaws))
354		if derr != nil {
355			var usageErr *delegationUsageError
356			if errors.As(derr, &usageErr) {
357				fmt.Fprintf(os.Stderr, "usage error: %v\n", derr)
358				os.Exit(2)
359			}
360			fail(derr)
361		}
362	
363		store, err := govflow.Open(cf.state)
364		if err != nil {
365			fail(err)
366		}
367		defer store.Close()
368		in := &govflow.CreateVoteInput{
369			ID:          *id,
370			Members:     []govflow.VoteMember(members),
371			Delegations: delegations,
372			Quorum:      quorum,
373			StartAt:     start,
374			Deadline:    deadline,
375			TimelockEnd: timelock,
376			Actions:     []string(actions),
377		}
378		view, existed, err := store.CreateVoteProposal(in)
379		if err != nil {
380			fail(err)
381		}
382		if cf.asJSON {
383			emitJSON(map[string]any{"proposal": view, "already_exists": existed})
384			return
385		}
386		if existed {
387			fmt.Printf("voting proposal %s already exists with identical content (state=%s)\n", view.ID, view.State)
388		} else {
389			fmt.Printf("created voting proposal %s: %d member(s), total_weight=%d, quorum=%d, voting=[%d,%d), timelock_end=%d, %d action(s)\n",
390				view.ID, len(view.Members), view.TotalWeight, view.Quorum, view.StartAt, view.Deadline, view.TimelockEnd, len(view.Actions))
391		}
392	}
