753	// ---- 持久化 ----
754	
755	// loadLocked 读取、严格解析并重放校验状态文件。调用方必须持锁。
756	func (s *Store) loadLocked() (*storedState, error) {
757		raw, err := os.ReadFile(s.path)
758		if err != nil {
759			return nil, err
760		}
761		if len(bytes.TrimSpace(raw)) == 0 {
762			return nil, fmt.Errorf("%w: %s: file is empty", ErrStateCorrupt, s.path)
763		}
764		// 先于结构扫描与解码逐字节校验字符串：非法 UTF-8 与未配对代理项转义
765		// 会被 encoding/json 悄悄改写成 U+FFFD 且不报错，必须在此明确拒绝，
766		// 使被改写的编号/账户名/动作原文不可能参与后续任何匹配与重放。
767		if err := checkStrictStrings(raw); err != nil {
768			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
769		}
770		if err := checkStateStructure(raw); err != nil {
771			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
772		}
773		var state storedState
774		dec := json.NewDecoder(bytes.NewReader(raw))
775		dec.DisallowUnknownFields()
776		if err := dec.Decode(&state); err != nil {
777			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
778		}
779		// 拒绝单个合法 JSON 之后再拼接的额外内容（如 "{} {}"）。
780		var extra json.RawMessage
781		if err := dec.Decode(&extra); err != io.EOF {
782			if err == nil {
783				err = fmt.Errorf("unexpected trailing content after state document: %s", strings.TrimSpace(string(extra)))
784			}
785			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
786		}
787		if err := validateState(&state); err != nil {
788			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
789		}
790		return &state, nil
791	}
792	
793	// commitLocked 序列化状态并以“临时文件 + fsync + 原子改名 + 目录 fsync”提交。
794	// 任一步失败都保留上次完整状态。调用方必须持锁。
795	func (s *Store) commitLocked(state *storedState) error {
796		if err := validateState(state); err != nil {
797			return fmt.Errorf("refusing to persist invalid state: %w", err)
798		}
799		payload, err := json.MarshalIndent(state, "", "  ")
800		if err != nil {
801			return err
802		}
803		payload = append(payload, '\n')
804	
805		dir := filepath.Dir(s.path)
806		tmp, err := os.CreateTemp(dir, ".govflow-state-*")
807		if err != nil {
808			return err
809		}
810		tmpName := tmp.Name()
811		cleanup := func() { _ = os.Remove(tmpName) }
812		if _, err := tmp.Write(payload); err != nil {
813			_ = tmp.Close()
814			cleanup()
815			return err
816		}
817		if err := tmp.Sync(); err != nil {
818			_ = tmp.Close()
819			cleanup()
820			return err
821		}
822		if err := tmp.Close(); err != nil {
823			cleanup()
824			return err
825		}
826		if err := os.Chmod(tmpName, 0o600); err != nil {
827			cleanup()
828			return err
829		}
830		if err := os.Rename(tmpName, s.path); err != nil {
831			cleanup()
832			return err
833		}
834		if err := syncDir(dir); err != nil {
835			return err
836		}
837		return nil
838	}
839	
840	func syncDir(dir string) error {
841		d, err := os.Open(dir)
842		if err != nil {
843			return err
844		}
845		defer d.Close()
846		return d.Sync()
847	}
848	
849	// validateState 做结构校验并重放全部凭据，确认余额与凭据完全一致。
850	func validateState(state *storedState) error {
851		if state.Magic != stateMagic {
852			return fmt.Errorf("bad magic %q", state.Magic)
853		}
854		if state.Version != stateVersion {
855			return fmt.Errorf("unsupported state version %d", state.Version)
856		}
857		if state.InitialTreasury < 0 {
858			return errors.New("initial treasury balance is negative")
859		}
860		if state.Treasury < 0 {
861			return errors.New("treasury balance is negative")
862		}
863		if state.Balances == nil {
864			return errors.New("balances table is missing")
865		}
866		if state.Proposals == nil {
867			return errors.New("proposals table is missing")
868		}
869		if state.Receipts == nil {
870			return errors.New("receipts table is missing")
871		}
872		// VoteProposals 缺省视为空表：旧版本写出的状态文件不含投票提案，继续可读。
873		if state.VoteProposals == nil {
874			state.VoteProposals = map[string]*storedVoteProposal{}
875		}
876		for account, balance := range state.Balances {
877			if account == "" {
878				return errors.New("balance entry with empty account")
879			}
880			if balance < 0 {
881				return fmt.Errorf("balance of %q is negative", account)
882			}
883		}
884		for key, p := range state.Proposals {
885			if p == nil {
886				return fmt.Errorf("proposal %q is empty", key)
887			}
888			if p.ID != key || p.ID == "" {
889				return fmt.Errorf("proposal key %q does not match id %q", key, p.ID)
890			}
891			if p.State != "passed" && p.State != "executed" {
892				return fmt.Errorf("proposal %q has unknown state %q", p.ID, p.State)
893			}
894			// 动作原文登记时原样保存；空串或非法原文留待执行时拒绝。
895		}
896		if err := validateVoteProposals(state); err != nil {
897			return err
898		}
899	
900		// 重放凭据：从初始资金库余额出发，按成功顺序重放每笔转账，
901		// 校验凭据内的前后余额、最终资金库与各账户余额，并检查状态一致性。
902		simTreasury := state.InitialTreasury
903		simBalances := map[string]int64{}
904		seenReceipts := map[string]int{}
905		for order, rcpt := range state.Receipts {
906			if rcpt == nil {
907				return fmt.Errorf("receipt %d is empty", order)
908			}
909			// order 是执行留痕中明确保存的成功提交序号（0 起），必须显式写出、
910			// 为 int64 范围内的非负整数且恰好等于凭据在记录表中的位置：第一份
911			// 凭据缺 order 也不能补成 0。缺失/空值/类型不符/位置不符都带提案
912			// 编号与字段报损坏，不按数组位置重新编号。
913			if err := validateReceiptOrder(order, rcpt); err != nil {
914				return err
915			}
916			if prev, dup := seenReceipts[rcpt.ProposalID]; dup {
917				return fmt.Errorf("duplicate receipt for %q at positions %d and %d", rcpt.ProposalID, prev, order)
918			}
919			seenReceipts[rcpt.ProposalID] = order
920			ownerState, ownerTimelock, ownerActions, found := proposalOwnerState(state, rcpt.ProposalID)
921			if !found {
922				return fmt.Errorf("receipt %q references an unregistered proposal", rcpt.ProposalID)
923			}
924			if ownerState != "executed" {
925				return fmt.Errorf("proposal %q has receipt but state is %q", rcpt.ProposalID, ownerState)
926			}
927			// 保存的凭据与首次执行受同一条执行资格规则约束：executed_at 必须明确
928			// 写出且不得早于提案时间锁。登记提案与投票提案共用这一判断。
929			if err := validateReceiptExecutedAt(order, rcpt, ownerTimelock); err != nil {
930				return err
931			}
932			// 每项动作的 index 与四个余额字段（资金库/收款账户 × before/after）
933			// 都必须明确写出：任何一个缺失、为 null 或类型不符都判整份状态损坏，
934			// 不能按数组位置、转账金额、账户余额或其它凭据补出；明确写出的 0 是
935			// 合法记录（第一项动作的 index 0 必须显式保存）。
936			for i := range rcpt.Actions {
937				if err := validateReceiptActionIndex(rcpt.ProposalID, i, &rcpt.Actions[i]); err != nil {
938					return err
939				}
940				if err := validateReceiptActionBalances(rcpt.ProposalID, i, &rcpt.Actions[i]); err != nil {
941					return err
942				}
943			}
944			// 凭据声明的逐笔转账由统一转账规则（verifyReceiptTransfers）重放
945			// 核对：动作条数/编号/原文、资金库与收款账户前后余额任一不符都带
946			// 动作位置报损坏原因；本函数随即返回错误，整份状态被拒绝，重放结果
947			// 不会被查询或落盘采纳。
948			var verr error
949			simTreasury, verr = verifyReceiptTransfers(rcpt, ownerActions, simTreasury, simBalances)
950			if verr != nil {
951				return verr
952			}
953		}
954		if simTreasury != state.Treasury {
955			return fmt.Errorf("treasury balance %d does not match receipt replay %d", state.Treasury, simTreasury)
956		}
957		// 余额表的账户集合必须与成功凭据涉及的收款账户完全一致：缺少收款账户、
958		// 出现无凭据支持的账户（即使写成 0）或已记录余额不符都判整份状态损坏。
959		// 不能只按账户数量或仅遍历文件自身的键：把一个已收款账户换成数量相同、
960		// 余额写成 0 的陌生账户时，数量相等且缺失键在 map 中读到零值，会被误判
961		// 为合法。账户名排序后报告，使错误信息确定且可读；余额表的排列顺序本身
962		// 不影响判定。
963		savedAccounts := make([]string, 0, len(state.Balances))
964		for account := range state.Balances {
965			savedAccounts = append(savedAccounts, account)
966		}
967		replayAccounts := make([]string, 0, len(simBalances))
968		for account := range simBalances {
969			replayAccounts = append(replayAccounts, account)
970		}
971		sort.Strings(savedAccounts)
972		sort.Strings(replayAccounts)
973		var missing, unexpected []string
974		si, ri := 0, 0
975		for si < len(savedAccounts) || ri < len(replayAccounts) {
976			switch {
977			case ri == len(replayAccounts) || (si < len(savedAccounts) && savedAccounts[si] < replayAccounts[ri]):
978				unexpected = append(unexpected, savedAccounts[si])
979				si++
980			case si == len(savedAccounts) || savedAccounts[si] > replayAccounts[ri]:
981				missing = append(missing, replayAccounts[ri])
982				ri++
983			default:
984				si++
985				ri++
986			}
987		}
988		if len(missing) > 0 || len(unexpected) > 0 {
989			problems := ""
990			if len(missing) > 0 {
991				problems = fmt.Sprintf("missing recipient account(s) %s with no balance record for funds actually received",
992					strings.Join(quoteAccounts(missing), ", "))
993			}
994			if len(unexpected) > 0 {
995				if problems != "" {
996					problems += "; "
997				}
998				problems += fmt.Sprintf("account(s) %s have balance records but no successful receipt supports them (a zero balance does not make an unsupported account legal)",
999					strings.Join(quoteAccounts(unexpected), ", "))
1000			}
1001			return fmt.Errorf("balance table is inconsistent with execution receipts: %s", problems)
1002		}
1003		for _, account := range replayAccounts {
1004			if balance := state.Balances[account]; balance != simBalances[account] {
1005				return fmt.Errorf("balance of %q is %d but receipt replay yields %d", account, balance, simBalances[account])
1006			}
1007		}
1008		// 已执行的提案必须有凭据；passed 提案不得有凭据（上面已部分保证）。
1009		for _, p := range state.Proposals {
1010			_, hasReceipt := seenReceipts[p.ID]
1011			if p.State == "executed" && !hasReceipt {
1012				return fmt.Errorf("proposal %q is executed without receipt", p.ID)
1013			}
1014		}
1015		for _, p := range state.VoteProposals {
1016			_, hasReceipt := seenReceipts[p.ID]
1017			if p.State == "executed" && !hasReceipt {
1018				return fmt.Errorf("voting proposal %q is executed without receipt", p.ID)
1019			}
1020		}
1021		return nil
1022	}
1023	
1024	// quoteAccounts 给账户名列表逐个加上 Go 风格引号，便于在损坏原因中逐字定位。
1025	func quoteAccounts(accounts []string) []string {
1026		quoted := make([]string, len(accounts))
1027		for i, account := range accounts {
1028			quoted[i] = strconv.Quote(account)
1029		}
1030		return quoted
1031	}
1032	
1033	// validateReceiptExecutedAt 严格判定一份已保存凭据的 executed_at：
1034	// 字段未写出、显式为 null 或不是 int64 整数都返回带定位的错误；
1035	// 明确写出的值必须不早于所属提案的 timelock_end（恰好等于时间锁有效，
1036	// 时间锁允许 0 时明确写出的 0 同样有效）。order 是凭据在凭据表中的
1037	// 位置（0 起），与提案编号一起用于定位。
1038	// “缺失/空值/类型不符”的判定与逐票明细、计票结果共用同一份规则
1039	// （requiredScalarProblem），此处只补充凭据的业务位置与执行资格检查。
1040	func validateReceiptExecutedAt(order int, rcpt *Receipt, timelockEnd int64) error {
1041		if problem := requiredScalarProblem(rcpt.executedAtRaw, scalarInteger); problem != "" {
1042			return fmt.Errorf("receipt %d for proposal %q field %q %s", order, rcpt.ProposalID, "executed_at", problem)
1043		}
1044		if rcpt.ExecutedAt < timelockEnd {
1045			return fmt.Errorf("receipt %d for proposal %q executed_at %d is before timelock_end %d",
1046				order, rcpt.ProposalID, rcpt.ExecutedAt, timelockEnd)
1047		}
1048		return nil
1049	}
1050	
1051	// validateReceiptOrder 严格判定一份已保存凭据的 order：它是执行留痕中明确
1052	// 保存的成功提交序号（0 起），字段未写出、显式为 null 或不是 int64 整数都
1053	// 返回带提案编号与字段的错误；类型合法但值与凭据在记录表中的实际位置不符
1054	// （含负数）则返回位置不符的错误。第一份凭据恰好排在位置 0 也不能因此把
1055	// 缺失字段补成 0——明确写出的 0 才是合法序号，缺失/null/写错类型一律拒绝。
1056	// position 是凭据在凭据表中的位置（0 起）。
1057	func validateReceiptOrder(position int, rcpt *Receipt) error {
1058		if problem := requiredScalarProblem(rcpt.orderRaw, scalarInteger); problem != "" {
1059			return fmt.Errorf("receipt %d for proposal %q field %q %s",
1060				position, rcpt.ProposalID, "order", problem)
1061		}
1062		if rcpt.Order != int64(position) {
1063			return fmt.Errorf("receipt %d for proposal %q field %q is %d, expected %d",
1064				position, rcpt.ProposalID, "order", rcpt.Order, position)
1065		}
1066		return nil
1067	}
1068	
1069	// validateReceiptActionIndex 严格判定一条动作留痕的 index：它是该动作在所属
1070	// 凭据中明确保存的位置编号（0 起）。字段未写出、显式为 null 或不是 int64
1071	// 整数（字符串、布尔、小数、指数写法、超界）返回带提案编号、动作位置与
1072	// 字段的错误；类型合法但值与动作的实际位置不符（含负数）返回位置不符错误。
1073	// 第一项动作缺失 index 不得被补成 0：只有明确写出的 0 才合法。position 是
1074	// 动作在凭据 actions 中的位置（0 起）。
1075	func validateReceiptActionIndex(id string, position int, ar *ActionReceipt) error {
1076		if problem := requiredScalarProblem(ar.indexRaw, scalarInteger); problem != "" {
1077			return fmt.Errorf("receipt for proposal %q action %d field %q %s",
1078				id, position, "index", problem)
1079		}
1080		if ar.Index != int64(position) {
1081			return fmt.Errorf("receipt for proposal %q action %d field %q is %d, expected %d",
1082				id, position, "index", ar.Index, position)
1083		}
1084		return nil
1085	}
1086	
1087	// validateReceiptActionBalances 严格判定一条动作留痕的四个余额字段：
1088	// 资金库与收款账户两侧的 before/after 都必须明确写出、非 null 且为 int64
1089	// 整数。任何一个字段缺失都判整份状态损坏，不能根据转账金额、账户余额或
1090	// 其它凭据补出它——即使按其余记录推算该字段本来应为 0。明确写出的整数 0
1091	// 是合法记录（如资金库恰好扣到 0、收款账户首次收款前为 0），不得当成缺失。
1092	// index 是动作在凭据中的下标（0 起），与提案编号、所在侧一起用于定位。
1093	// “缺失/空值/类型不符”的判定与逐票明细、计票结果、executed_at 共用同一份
1094	// 规则（validateRawFields），此处只补充业务位置：提案编号 + 动作下标 + 侧。
1095	func validateReceiptActionBalances(id string, index int, ar *ActionReceipt) error {
1096		sides := []struct {
1097			name   string
1098			update *BalanceUpdate
1099		}{
1100			{"treasury", &ar.Treasury},
1101			{"recipient", &ar.Recipient},
1102		}
1103		for _, side := range sides {
1104			err := validateRawFields([]rawField{
1105				{name: "before", kind: scalarInteger, raw: side.update.beforeRaw},
1106				{name: "after", kind: scalarInteger, raw: side.update.afterRaw},
1107			}, func(field, problem string) error {
1108				return fmt.Errorf("receipt for proposal %q action %d %s field %q %s",
1109					id, index, side.name, field, problem)
1110			})
1111			if err != nil {
1112				return err
1113			}
1114		}
1115		return nil
1116	}
1117	
1118	// ---- 结构检查：固定字段名逐字匹配 + 重复键拒绝 ----
1119	
1120	// schemaKind 是状态文件 JSON 在某一层的形状类别。
1121	type schemaKind int
1122	
1123	const (
1124		kindAny     schemaKind = iota // 叶子值：结构检查不深入，类型由解码器核对
1125		kindObject                    // 固定字段对象：键必须与保存格式的字段名逐字一致
1126		kindMap                       // 业务编号表：键是自由文本（账户名、提案编号）
1127		kindArray                     // 数组
1128		kindString                    // 叶子：必须是 JSON 字符串
1129		kindBoolean                   // 叶子：必须是 JSON 布尔值（不接受字符串/数字/null）
1130		kindInteger                   // 叶子：必须是 int64 范围内的 JSON 整数（不接受小数/指数/字符串/null）
1131	)
1132	
1133	// schemaNode 描述状态文件某一层允许的形状。整棵树由 storedState 的 json tag
1134	// 反射生成，字段名集合因此永远与保存格式一致，不会随结构演进而漂移。
1135	type schemaNode struct {
1136		kind   schemaKind
1137		fields map[string]*schemaNode // kindObject：字段名 → 值的形状
1138		elem   *schemaNode            // kindMap/kindArray：值/元素的形状
1139	}
1140	
1141	// schemaOf 按 encoding/json 的字段名规则（json tag 优先，缺省用字段名）推导形状。
1142	func schemaOf(t reflect.Type) *schemaNode {
1143		for t.Kind() == reflect.Pointer {
1144			t = t.Elem()
1145		}
1146		switch t.Kind() {
1147		case reflect.Struct:
1148			node := &schemaNode{kind: kindObject, fields: map[string]*schemaNode{}}
1149			for i := 0; i < t.NumField(); i++ {
1150				f := t.Field(i)
1151				if f.PkgPath != "" { // 未导出字段不参与 JSON
1152					continue
1153				}
1154				name := f.Name
1155				if tag, ok := f.Tag.Lookup("json"); ok {
1156					tagName, _, _ := strings.Cut(tag, ",")
1157					if tagName == "-" {
1158						continue
1159					}
1160					if tagName != "" {
1161						name = tagName
1162					}
1163				}
1164				node.fields[name] = schemaOf(f.Type)
1165			}
1166			return node
1167		case reflect.Map:
1168			return &schemaNode{kind: kindMap, elem: schemaOf(t.Elem())}
1169		case reflect.Slice, reflect.Array:
1170			return &schemaNode{kind: kindArray, elem: schemaOf(t.Elem())}
1171		case reflect.String:
1172			return &schemaNode{kind: kindString}
1173		case reflect.Bool:
1174			return &schemaNode{kind: kindBoolean}
1175		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
1176			reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
1177			return &schemaNode{kind: kindInteger}
1178		default:
1179			return &schemaNode{kind: kindAny}
1180		}
1181	}
1182	
1183	var storedStateSchema = schemaOf(reflect.TypeOf(storedState{}))
1184	
1185	func init() {
1186		// 票据的四个标量字段（representative/weight/support/voted_at）由
1187		// validateStoredBallot 逐票判定“缺失/空值/类型不符”，其错误原因需要带上
1188		// 提案编号、票据下标与字段名；因此结构扫描在这些叶子位置保持宽松（kindAny），
1189		// 不抢在解码器之前用不含票据定位的通用信息报错。
1190		ballotFields := storedStateSchema.fields["vote_proposals"].elem.fields["ballots"].elem.fields
1191		for _, name := range []string{"representative", "weight", "support", "voted_at"} {
1192			ballotFields[name].kind = kindAny
1193		}
1194		// 计票结果的两个权重字段（for_weight/against_weight）同理：缺失/空值/
1195		// 类型不符的判定需要带上提案编号，统一由 validateStoredTally 报错，
1196		// 结构扫描在这两个叶子位置保持宽松。tallied_at 保持严格整数叶子，
1197		// 其“不早于截止”的既有校验不变。
1198		tallyFields := storedStateSchema.fields["vote_proposals"].elem.fields["tally"].fields
1199		for _, name := range []string{"for_weight", "against_weight"} {
1200			tallyFields[name].kind = kindAny
1201		}
1202		// 凭据的 executed_at 同理：缺失/空值/类型不符/早于时间锁的判定需要带上
1203		// 提案编号与凭据位置，统一由 validateReceiptExecutedAt 报错，结构扫描在此
1204		// 叶子位置保持宽松。
1205		receiptFields := storedStateSchema.fields["receipts"].elem.fields
1206		receiptFields["executed_at"].kind = kindAny
1207		// 凭据的 order 同理：缺失/空值/类型不符/位置不符的判定需要带上提案编号与
1208		// 凭据位置，统一由 validateReceiptOrder 报错，结构扫描在此叶子位置保持宽松。
1209		receiptFields["order"].kind = kindAny
1210		// 凭据逐笔留痕的 index 同理：缺失/空值/类型不符/位置不符的判定需要带上
1211		// 提案编号与动作下标，统一由 validateReceiptActionIndex 报错，结构扫描在
1212		// 此叶子位置保持宽松。
1213		receiptFields["actions"].elem.fields["index"].kind = kindAny
1214		// 凭据逐笔留痕的四个余额字段（treasury/recipient 的 before/after）同理：
1215		// 缺失/空值/类型不符的判定需要带上提案编号、动作下标与所在侧，统一由
1216		// validateReceiptActionBalances 报错，结构扫描在这些叶子位置保持宽松。
1217		actionFields := receiptFields["actions"].elem.fields
1218		for _, side := range []string{"treasury", "recipient"} {
1219			balanceFields := actionFields[side].fields
1220			balanceFields["before"].kind = kindAny
1221			balanceFields["after"].kind = kindAny
1222		}
1223	}
1224	
1225	// scanFrame 是结构扫描的栈帧。
1226	type scanFrame struct {
1227		node    *schemaNode
1228		isArray bool
1229		opaque  bool // 形状不符或叶子位置的容器：只配对括号，类型错误交给解码器报告
1230		seen    map[string]bool
1231		atValue bool // 对象帧：下一个待消费 token 是值而非键
1232		index   int  // 数组帧：下一个元素下标
1233		path    string
1234	}
1235	
1236	func peekFrame(stack []*scanFrame) *scanFrame {
1237		if len(stack) == 0 {
1238			return nil
1239		}
1240		return stack[len(stack)-1]
1241	}
1242	
1243	// checkStateStructure 在解码前逐 token 扫描状态文件：
1244	//   - 同一对象内键（按 JSON 解读后的字符串，转义拼写与普通拼写视为同一键）不得重复；
1245	//   - 固定字段对象的键必须与保存格式的字段名逐字一致：大小写变体（如 Treasury、
1246	//     Support）与未知字段一样拒绝，避免解码器的大小写折叠把两份值并入同一字段；
1247	//   - balances/proposals/vote_proposals 等业务编号表的键是自由文本，
1248	//     Audit 与 audit、GIP-1 与 gip-1 是不同账户/编号，不做字段名检查。
1249	//
1250	// 报错带有出问题的字段与所在记录的路径（如 vote_proposals["GIP-1"].ballots[0]），
1251	// 便于定位。字段顺序、缩进与合法转义不影响判定。
1252	func checkStateStructure(raw []byte) error {
1253		dec := json.NewDecoder(bytes.NewReader(raw))
1254		// UseNumber：数字 token 保留词面写法，整数叶子可据此精确判定 int64 范围，
1255		// 不被 float64 在 2^63 附近的舍入混淆（MaxInt64 与 MaxInt64+1 会折成同一浮点）。
1256		dec.UseNumber()
1257		var stack []*scanFrame
1258		// 对象帧读到键时，把该键对应值的形状与路径暂存于此，供紧随其后的值使用。
1259		pendingNode := storedStateSchema
1260		pendingPath := "state"
1261	
1262		// 一个值消费完毕：推进父帧的键/值位置或数组下标。
1263		finishValue := func() {
1264			top := peekFrame(stack)
1265			if top == nil || top.opaque {
1266				return
1267			}
1268			if top.isArray {
1269				top.index++
1270			} else {
1271				top.atValue = false
1272			}
1273		}
1274	
1275		for {
1276			tok, err := dec.Token()
1277			if err == io.EOF {
1278				if len(stack) != 0 {
1279					return errors.New("unterminated object or array")
1280				}
1281				return nil
1282			}
1283			if err != nil {
1284				return err
1285			}
1286	
1287			if top := peekFrame(stack); top != nil && top.opaque {
1288				// 不透明容器内不做字段检查，只配对括号。
1289				if d, ok := tok.(json.Delim); ok {
1290					if d == '{' || d == '[' {
1291						stack = append(stack, &scanFrame{opaque: true})
1292					} else {
1293						stack = stack[:len(stack)-1]
1294						finishValue()
1295					}
1296				}
1297				continue
1298			}
1299	
1300			if top := peekFrame(stack); top != nil && !top.isArray && !top.atValue {
1301				// 对象帧的键位置：闭括号或下一个键。
1302				if d, ok := tok.(json.Delim); ok {
1303					if d != '}' {
1304						return fmt.Errorf("unexpected %q inside object at %s", string(d), top.path)
1305					}
1306					stack = stack[:len(stack)-1]
1307					finishValue()
1308					continue
1309				}
1310				key, ok := tok.(string)
1311				if !ok {
1312					return errors.New("object key must be a string")
1313				}
1314				if top.seen[key] {
1315					return fmt.Errorf("duplicate key %q at %s", key, top.path)
1316				}
1317				top.seen[key] = true
1318				top.atValue = true
1319				switch top.node.kind {
1320				case kindObject:
1321					child, known := top.node.fields[key]
1322					if !known {
1323						return fmt.Errorf("unknown field %q at %s", key, top.path)
1324					}
1325					pendingNode = child
1326					pendingPath = top.path + "." + key
1327				case kindMap:
1328					// 业务编号是自由文本，大小写变体属于不同编号，不得拒绝或合并。
1329					pendingNode = top.node.elem
1330					pendingPath = top.path + "[" + strconv.Quote(key) + "]"
1331				}
1332				continue
1333			}
1334	
1335			// 值位置：对象键之后的值或数组元素。
1336			node := pendingNode
1337			path := pendingPath
1338			if top := peekFrame(stack); top != nil && top.isArray {
1339				node = top.node.elem
1340				path = top.path + "[" + strconv.Itoa(top.index) + "]"
1341			}
1342			if d, ok := tok.(json.Delim); ok {
1343				switch d {
1344				case '{', '[':
1345					frame := &scanFrame{isArray: d == '[', path: path}
1346					shapeOK := (d == '{' && (node.kind == kindObject || node.kind == kindMap)) ||
1347						(d == '[' && node.kind == kindArray)
1348					if !shapeOK {
1349						// 叶子位置出现容器或形状不符：跳过内容，类型错误由解码器报告。
1350						frame.opaque = true
1351					} else {
1352						frame.node = node
1353						if d == '{' {
1354							frame.seen = map[string]bool{}
1355						}
1356					}
1357					stack = append(stack, frame)
1358				default: // '}' 或 ']'：数组结束（对象的闭括号已在键位置处理）
1359					if len(stack) == 0 {
1360						return errors.New("unexpected closing delimiter")
1361					}
1362					stack = stack[:len(stack)-1]
1363					finishValue()
1364				}
1365				continue
1366			}
1367			// 标量值（含 null）：严格叶子必须与字段声明的 JSON 类型逐字一致，
1368			// null 不允许用来顶替字符串/布尔/整数。
1369			if err := checkLeafScalar(node, path, tok); err != nil {
1370				return err
1371			}
1372			finishValue()
1373		}
1374	}
1375	
1376	// leafKindName 是严格叶子类型在错误信息中的人类可读名称。
1377	func leafKindName(k schemaKind) string {
1378		switch k {
1379		case kindString:
1380			return "string"
1381		case kindBoolean:
1382			return "boolean"
1383		case kindInteger:
1384			return "integer"
1385		default:
1386			return "value"
1387		}
1388	}
1389	
1390	// tokenKindName 归类一个标量 token 实际写出的 JSON 类型。
1391	func tokenKindName(tok json.Token) string {
1392		switch v := tok.(type) {
1393		case nil:
1394			return "null"
1395		case string:
1396			return "string"
1397		case bool:
1398			return "boolean"
1399		case json.Number:
1400			if _, err := strconv.ParseInt(string(v), 10, 64); err == nil {
1401				return "integer"
1402			}
1403			return "number"
1404		default:
1405			return "value"
1406		}
1407	}
1408	
1409	// checkLeafScalar 校验严格标量叶子：字符串/布尔/int64 整数位置出现 null 或
1410	// 其它 JSON 类型即判结构损坏。非整数（小数、指数）或超出 int64 的整数同样拒绝。
1411	func checkLeafScalar(node *schemaNode, path string, tok json.Token) error {
1412		switch node.kind {
1413		case kindString, kindBoolean, kindInteger:
1414		default:
1415			return nil
1416		}
1417		if node.kind == kindInteger {
1418			if n, ok := tok.(json.Number); ok {
1419				if _, err := strconv.ParseInt(string(n), 10, 64); err != nil {
1420					return fmt.Errorf("field at %s must be an int64 integer, got %s", path, string(n))
1421				}
1422				return nil
1423			}
1424		}
1425		want := leafKindName(node.kind)
1426		if got := tokenKindName(tok); got != want {
1427			return fmt.Errorf("field at %s must be %s, got %s", path, want, got)
1428		}
1429		return nil
1430	}
1431

